import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-03-22","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-03-22","date":"2022-03-22T00:00:00.000Z","updated":"2022-03-30T00:00:00.000Z","tags":["Ceph","Service Discovery","High Availability","Rook","NFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-03-22.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-03-22.md","lastUpdated":1780460162000}'),l={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-03-22.md"};function o(h,a,s,n,c,d){return t(),i("div",null,[...a[0]||(a[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-服务发现与高可用性-ha-讨论" tabindex="-1">会议主题：服务发现与高可用性（HA）讨论 <a class="header-anchor" href="#会议主题-服务发现与高可用性-ha-讨论" aria-label="Permalink to &quot;会议主题：服务发现与高可用性（HA）讨论&quot;">​</a></h4><h4 id="参会人员-ceph研发团队成员" tabindex="-1">参会人员：Ceph研发团队成员 <a class="header-anchor" href="#参会人员-ceph研发团队成员" aria-label="Permalink to &quot;参会人员：Ceph研发团队成员&quot;">​</a></h4><h4 id="会议日期-2022年3月22日" tabindex="-1">会议日期：2022年3月22日 <a class="header-anchor" href="#会议日期-2022年3月22日" aria-label="Permalink to &quot;会议日期：2022年3月22日&quot;">​</a></h4><h4 id="会议地点-视频会议" tabindex="-1">会议地点：视频会议 <a class="header-anchor" href="#会议地点-视频会议" aria-label="Permalink to &quot;会议地点：视频会议&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>服务发现（Service Discovery）</strong></p><ul><li>讨论在Ceph中添加新端点以支持服务发现的需求，希望通过HTTP从外部获取当前配置。</li><li>现有端点URL在代码中硬编码，建议考虑服务发现层级，以便集群内部客户端更容易发现服务。</li><li>挑战在于集群内的名称解析和IP硬编码问题，建议使用虚拟IP（VIP）或高可用性代理（HA Proxy）简化服务发现。</li></ul></li><li><p><strong>Rook测试失败更新</strong></p><ul><li>Rook测试套件中出现的故障问题，决定移除未维护的编排器（Orchestrator）命令测试，以清理测试套件。</li><li>后续行动：继续监控和更新该问题。</li></ul></li><li><p><strong>高可用性NFS（HA NFS）</strong></p><ul><li>测试结果显示，NFS守护进程在节点离线后能够重新调度，但恢复时间较长（约1-2分钟）。</li><li>建议：添加MDS到调度列表，优化心跳检测机制，探索使用代理进行更快速的心跳检测。</li><li>未来工作：解决端口冲突问题以支持守护进程的共存。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续使用当前的服务发现方法，同时考虑长期改进方案。</li><li>移除Rook测试套件中的未维护编排器命令测试。</li><li>优化NFS和MDS的高可用性配置，特别是心跳检测和重新调度机制。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续监控和更新Rook测试失败问题。</li><li>与Jeff Leighton讨论NFS和MDS的调度策略。</li><li>探索使用代理进行更快速的心跳检测，并解决端口冲突问题。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><p>会议于具体时间结束，下次会议预定于下周进行。</p>',13)])])}const _=e(l,[["render",o]]);export{u as __pageData,_ as default};
